 where d.id=w.dispatch_receipt_id and d.master_session_id='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid and d.authority_receipt_id=w.id
 and d.request_key=w.request_key and d.event_kind='mission_generic_event'
 and d.renderer_version='mission-generic-runtime/1' and d.status='failed' and d.finalized_at is not null
 and d.dispatch_count=0 and d.charged_cost_usd=0 and d.upper_bound_cost_usd=0
 and d.lease_token_sha256 is null and d.lease_expires_at is null
 and not exists(select 1 from mission_narrative_internal.dispatch_attempts da where da.receipt_id=d.id)
 and not exists(select 1 from mission_narrative_internal.provider_authorizations pa where pa.receipt_id=d.id)
 and exists(select 1 from mission_narrative_internal.dispatch_audit audit
 where audit.receipt_id=d.id and audit.event_code='generic_pre_provider_failed'
 and audit.details=jsonb_build_object('work_id',w.id,'receipt_id',w.receipt_id,
 'failure_code',w.result->>'failure_code','provider_calls',0,'charged_cost_usd',0,'result_sha256',w.result_sha256))))))
 and not exists(select 1 from public.combat_v2_sessions s where s.master_session_id='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid
  and (public.combat_v2_values_written(s.id) is distinct from false or combat_panel_private.uses_simulated_pools(s.id) is distinct from true))))) AND w.authorization_id IS NULL AND w.dispatch_id IS NULL AND b.writer_work_id=w.id AND b.state='ready' AND b.message_id IS NULL AND w.payload_sha256='da8c38c23db1c04ceaaaedfb7b5ead1b43c18c1ee60b069696ba36d832c9da78') THEN RAISE EXCEPTION 'C24_ENABLE_READY_CHANGED';END IF;
IF EXISTS(SELECT 1 FROM public.master_v2_sessions s WHERE s.id<>'ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid AND s.owner_kind='ai_service' AND s.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND s.closed_at IS NULL) THEN RAISE EXCEPTION 'C24_ENABLE_OTHER_SCENE';END IF;
IF public._combat_presente('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid) IS DISTINCT FROM TRUE OR public._combat_presente('b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid,'0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'C24_ENABLE_PRESENCE';END IF;
IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c464_control cc CROSS JOIN mission_factory_owner.editor_release_readiness rr WHERE cc.singleton AND rr.singleton AND cc.review_sha256=rr.canonical_preimage::jsonb#>>'{config,staff_finite_ia_budget,composed_review_sha256}' AND rr.independent_review_ref=rr.canonical_preimage::jsonb#>>'{config,staff_finite_ia_budget,composed_review_ref}' AND cc.review_sha256=$ctx24active$dbd6f5fc18a024803855a32f2e4e8100a4146dc3e50ff7e49085e09f57b8a129$ctx24active$) THEN RAISE EXCEPTION 'C24_ENABLE_REVIEW_BINDINGS';END IF;
UPDATE mission_factory_owner.c464_control SET runtime_enabled=true,expires_at=clock_timestamp()+interval '15 minutes' WHERE singleton AND release_sha256=$ctx24active$06c87c0d0e107c0c7bc9c56e916c0e15f221801babf0badb7739ddde6804b5b6$ctx24active$ AND NOT authoring_enabled;IF NOT FOUND THEN RAISE EXCEPTION 'C24_ENABLE_G2';END IF;
UPDATE mission_factory_owner.provider_authoring_runtime SET enabled=true WHERE singleton AND release_sha256=$ctx24active$06c87c0d0e107c0c7bc9c56e916c0e15f221801babf0badb7739ddde6804b5b6$ctx24active$ AND qualified AND edge_qualified;IF NOT FOUND THEN RAISE EXCEPTION 'C24_ENABLE_PROVIDER';END IF;
UPDATE mission_factory_owner.provider_authoring_admissions SET enabled=true,expires_at=(SELECT expires_at FROM mission_factory_owner.c464_control WHERE singleton) WHERE NOT enabled AND release_sha256=$ctx24active$06c87c0d0e107c0c7bc9c56e916c0e15f221801babf0badb7739ddde6804b5b6$ctx24active$ AND actor_user IN('f0856d53-83a6-4de0-bc0c-12c87916e665'::uuid,'b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid) AND location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid;GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>2 THEN RAISE EXCEPTION 'C24_ENABLE_ADMISSION_COUNT';END IF;
UPDATE mission_factory_owner.editor_release_readiness SET state='enabled',updated_at=clock_timestamp() WHERE singleton AND revision_sha256=$ctx24active$06c87c0d0e107c0c7bc9c56e916c0e15f221801babf0badb7739ddde6804b5b6$ctx24active$;
IF NOT EXISTS(SELECT 1 FROM mission_factory_owner.c464_control cc CROSS JOIN mission_factory_owner.editor_release_readiness rr WHERE cc.singleton AND rr.singleton AND cc.review_sha256=rr.canonical_preimage::jsonb#>>'{config,staff_finite_ia_budget,composed_review_sha256}' AND rr.independent_review_ref=rr.canonical_preimage::jsonb#>>'{config,staff_finite_ia_budget,composed_review_ref}' AND cc.review_sha256=$ctx24active$dbd6f5fc18a024803855a32f2e4e8100a4146dc3e50ff7e49085e09f57b8a129$ctx24active$) THEN RAISE EXCEPTION 'C24_ENABLE_REVIEW_BINDINGS';END IF;
IF mission_generic_owner.c726_factory_staff_runtime_v1('ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid) IS DISTINCT FROM TRUE OR mission_generic_owner.c8_context24_scope_v1('48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'C24_ENABLE_CURRENT_SCOPE_CLOSED';END IF;

DECLARE p_session uuid:='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid;p_next boolean:=true;p_current_work uuid:='48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid;
a mission_generic_owner.dispatch_admissions;g mission_generic_owner.provider_policy;
 pol mission_narrative_internal.runtime_policy;spent numeric;calls bigint;bound numeric;capcost numeric;capcalls integer;ok boolean;
begin
 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 -- Same admission/policy locks at claim and all subsequent boundaries.
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=p_session for update;
 select * into strict g from mission_generic_owner.provider_policy where singleton for share;
 if not a.c7_budget_enforced then budget:=jsonb_build_object('enforced',false,'allowed',true,'remaining_calls',a.call_limit-a.calls_authorized);else
 if a.c7_budget_qualification_sha256 is null or a.call_limit<1 or a.cost_budget_usd<=0
 then raise exception 'MGPG_C7_BUDGET_UNQUALIFIED' using errcode='55000';end if;
 IF p_session='ce7bc0e0-c8ed-48dd-a9ec-58c02022a7b9'::uuid AND mission_generic_owner.c8_context24_scope_v1('48e1bdcd-f044-be8c-1923-54d38e7e822c'::uuid) THEN pol.max_input_tokens:=24000;pol.max_output_tokens:=20000;END IF;
 bound:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 capcost:=least(g.run_budget_usd,a.cost_budget_usd,coalesce(pol.run_budget_usd,g.run_budget_usd));
 capcalls:=2*least(g.max_run_calls,a.call_limit);
 -- A claimed Native work is already a logical reservation, even before reserve HTTP.
 -- Its bound is represented by existing work state; a receipt/attempt is not counted twice.
 select coalesce(sum(case when d.status in('success','fallback','unknown_billable')
   then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
   when wi.state in('claimed','authorized','provider_started') then greatest(coalesce(d.upper_bound_cost_usd,0),bound)
   else coalesce(d.upper_bound_cost_usd,0) end + case when ca.details is not null then (ca.details->>'count_upper_cost_usd')::numeric when wi.state in('claimed','authorized','provider_started') then coalesce(a.c8_count_upper_cost_usd,0) else 0 end),0),
 coalesce(sum(case when wi.state in('claimed','authorized','provider_started') then 2 else (case when ca.details is not null then 1 else 0 end)+(case when d.upper_bound_cost_usd is not null or exists(select 1 from mission_narrative_internal.dispatch_attempts da where da.receipt_id=d.id) then 1 else 0 end) end),0)
 into spent,calls from mission_generic_owner.work_items wi
 left join mission_narrative_internal.dispatch_receipts d on d.id=wi.dispatch_receipt_id
 left join mission_narrative_internal.dispatch_audit ca on ca.receipt_id=d.id and ca.event_code='c8_count_started'
 where wi.master_session_id=p_session and (p_current_work is null or wi.id<>p_current_work)
 and (wi.dispatch_receipt_id is not null or wi.state in('claimed','authorized','provider_started'));
 calls:=greatest(calls,a.calls_authorized-case when p_current_work is not null and exists(
  select 1 from mission_generic_owner.work_items wi where wi.id=p_current_work and wi.authorization_id is not null) then 1 else 0 end);
 ok:=a.enabled and g.enabled and a.c8_count_qualification_sha256 is not null and a.c8_count_upper_cost_usd is not null and bound>=0 and bound<'Infinity'::numeric and capcost>0 and capcalls>0
 and spent+case when p_next then bound+a.c8_count_upper_cost_usd else 0 end<=capcost
 and calls+case when p_next then 2 else 0 end<=capcalls;
 budget:=jsonb_build_object('enforced',true,'allowed',ok,'remaining_calls',greatest(0,capcalls-calls),
 'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',capcalls,'cost_limit_usd',capcost,
 'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2);
end if;
end;
IF budget->>'enforced' IS DISTINCT FROM 'true' OR budget->>'allowed' IS DISTINCT FROM 'true' OR (budget->>'remaining_calls')::integer<2 OR (budget->>'upper_bound_next_usd')::numeric<>0.0124 OR (budget->>'count_upper_cost_usd')::numeric<>0.0124 OR (budget->>'call_limit')::integer<>28 OR (budget->>'cost_limit_usd')::numeric>0.3136 THEN RAISE EXCEPTION 'C24_ENABLE_C7_NO_PAIR';END IF;END $ctx24enable15$;COMMIT;
